# Bank pages: "<Bank> investment banking interview: process, questions and how to prepare".
# Process facts come from the sources listed on each page (read 2026-11-10). Application timing comes from
# The Wire's application tracker (data/wire.json APP_OPEN). Build with: python3 guides/_src/extra.py
import json, os
S = lambda pairs: "Sources: " + " · ".join(f'<a href="{u}" rel="nofollow">{n}</a>' for n, u in pairs)
_W = json.load(open(os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "..", "data", "wire.json"), encoding="utf-8"))
def when(bank):
    for a in _W.get("APP_OPEN", []):
        if a[0] == bank and "Summer" in a[1]:
            return f'M&amp;A Prep\'s <a href="/#recruit">application tracker</a> lists the {a[1]} as <b>{a[5]}</b>. Postings can open and close early, so check the bank\'s careers site often.'
    return 'Track openings on M&amp;A Prep\'s <a href="/#recruit">application tracker</a>.'

CTA = ("cta", "Practice these questions out loud in 5-minute levels, free.", "/", "Start training on M&A Prep")
TEST = ("p", 'Not sure if you\'re ready? Take the free <a href="/tools/superday-readiness-test/">Superday readiness test</a> (12 questions, 3 minutes).')
def prep(bank, extra):
    return [("h2", f"How to prepare for {bank}"),
        ("card", "Do these before your first round", extra + [
            "Know the core technicals cold: how the 3 statements link, enterprise value vs. equity value, a DCF walkthrough and a paper LBO. See the <a href=\"/guides/investment-banking-interview-questions/\">IB interview questions guide</a>.",
            "Have a 60-second \"walk me through your resume\" and a specific <a href=\"/guides/why-investment-banking-answer/\">why investment banking</a> answer.",
            f"Prepare a real \"why {bank}\" answer: a recent deal, a group you want, and a person you spoke with.",
            "Follow the markets for 2 weeks before interviews and have one stock pitch ready (<a href=\"/guides/how-to-pitch-a-stock-interview/\">how to pitch a stock</a>)."])]
PAY = ("p", 'What does it pay? See <a href="/tools/investment-banking-pay/">investment banking pay by level</a> (analyst to MD, by bank type).')

def bank(slug, name, short_kind, lede, stages, emph, qs, faq, extra, src, related):
    return {"slug": slug, "short": f"{name} interview guide",
        "title": f"{name} Investment Banking Interview: Process, Questions & Prep",
        "h1": f"{name} investment banking interview guide",
        "desc": f"How the {name} investment banking summer analyst interview works: each round, what interviewers focus on, the questions to practice, and when applications open.",
        "related": related + ["investment-banking-interview-questions", "investment-banking-recruiting-timeline"],
        "lede": lede,
        "body": [("h2", "The interview process, step by step"),
            ("table", ["Round", "What happens"], stages),
            ("p", when(name)),
            ("h2", f"What {name} interviewers focus on"),
            ("card", short_kind, emph),
            ("h2", "Questions to practice"),
            ("table", ["Type", "Examples"], qs),
            *prep(name, extra), TEST, PAY,
            ("h2", "Common questions"), *[("qa", q, a) for q, a in faq],
            CTA, ("p", S(src) + ". Processes change every cycle; treat this as a typical pattern, not a guarantee.")]}

